const statusStyles: Record<string, string> = { Overdue: 'status-red', 'Dates missing': 'status-slate', 'Awaiting response': 'status-blue', 'Action required': 'status-amber', 'Under review': 'status-slate', Completed: 'status-green', 'Deadline approaching': 'status-red' };

// ---- Reminder helpers (shared by Deadlines and My RTIs). Dates are user-entered; the 30-day value is a reminder, not a legal determination.
const DAY_MS = 86400000;
const isActiveRTI = (r: RTIRecord) => !['Closed', 'Reply Received'].includes(r.status);
const parseISODate = (s?: string) => { if (!s || !/^\d{4}-\d{2}-\d{2}$/.test(s)) return null; const [year, month, day] = s.split('-').map(Number); const d = new Date(year, month - 1, day); if (d.getFullYear() !== year || d.getMonth() !== month - 1 || d.getDate() !== day) return null; return d; };
const toISODate = (d: Date) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
const fmtDate = (s: string) => { const d = parseISODate(s); return d ? d.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' }) : 'Not set'; };
type Reminder = { target: string; source: 'follow-up' | 'filed+30' | 'none'; days: number | null; state: 'missing' | 'overdue' | 'due-soon' | 'upcoming' };
function reminderFor(r: RTIRecord): Reminder {
  const follow = parseISODate(r.follow_up_date); const filed = parseISODate(r.filed_date);
  const target = follow ?? (filed ? new Date(filed.getFullYear(), filed.getMonth(), filed.getDate() + 30) : null);
  if (!target) return { target: '', source: 'none', days: null, state: 'missing' };
  const today = new Date(); today.setHours(0, 0, 0, 0);
  const days = Math.round((target.getTime() - today.getTime()) / DAY_MS);
  return { target: toISODate(target), source: follow ? 'follow-up' : 'filed+30', days, state: days < 0 ? 'overdue' : days <= 7 ? 'due-soon' : 'upcoming' };
}

